    "LARGEUR_BLOC_MIN_M": { "valeur": 1.5, "unite": "m", "ou": "model/toitMesure.ts", "pourquoi": "Un bloc coupe par une marche fait au moins cela de large.", "cas": [] },
    "CELLULES_MIN": { "valeur": 20, "unite": "cellules", "ou": "model/toitMesure.ts", "pourquoi": "Il faut au moins tant de cellules sous le contour, et au moins la moitie des cellules du contour, pour un toit.", "cas": [] },
    "EGOUT_MESURE_MIN_M": { "valeur": 1.8, "unite": "m", "ou": "model/toitMesure.ts (EGOUT_MIN_M)", "pourquoi": "Borne basse de l'egout lu sur la surface mesuree.", "cas": [] },
    "EGOUT_MESURE_MAX_M": { "valeur": 40, "unite": "m", "ou": "model/toitMesure.ts (EGOUT_MAX_M)", "pourquoi": "Borne haute de l'egout lu sur la surface mesuree.", "cas": [] },
    "PAS_PROFIL_M": { "valeur": 0.5, "unite": "m", "ou": "model/toitMesure.ts", "pourquoi": "Le pas des hauteurs lues le long d'un mur, pour sa hauteur mesuree.", "cas": [] },

    "TOLERANCE_DEG": { "valeur": 15, "unite": "degres", "ou": "model/volumesToit.ts", "pourquoi": "Un cote a plus de cela d'un axe du batiment : le contour n'est pas rectiligne, pas de decoupage en rectangles.", "cas": [] },
