    "AIRE_NEGLIGEABLE_M2": { "valeur": 2, "unite": "m2", "ou": "model/volumesToit.ts", "pourquoi": "En dessous de cette aire, un rectangle etroit est oublie (un auvent, une marche) ; au-dela, le decoupage est refuse.", "cas": [] },
    "SEUIL_DECROCHE_M": { "valeur": 1.2, "unite": "m", "ou": "model/volumesToit.ts", "pourquoi": "Un cote plus court que cela est un decroche de facade (un ressaut, un conduit), pas un volume : il est lisse.", "cas": [] },

    "ECHANTILLONS_MIN": { "valeur": 20, "unite": "mesures", "ou": "facade/toits/toitLidar.ts", "pourquoi": "En dessous, on ne juge pas une forme : un abri de jardin fait une vingtaine de cellules.", "cas": [] },
    "ECART_MAX_M": { "valeur": 0.8, "unite": "m", "ou": "facade/toits/toitLidar.ts", "pourquoi": "Au-dela de cet ecart, aucune forme simple n'explique les mesures : le toit BD TOPO reste.", "cas": [] },
    "ECART_MAX_APPENTIS_M": { "valeur": 0.4, "unite": "m", "ou": "facade/toits/toitLidar.ts", "pourquoi": "Un appentis se contente de moins : une rampe explique a peu pres n'importe quoi, un vrai appentis colle de pres.", "cas": [] },
    "RESIDU_ABERRANT_M": { "valeur": 1.5, "unite": "m", "ou": "facade/toits/toitLidar.ts", "pourquoi": "Une mesure a plus de cela du toit ajuste est un arbre, une cheminee, une lucarne : ecartee, puis l'ajustement refait.", "cas": [] },
    "PART_HAUTE": { "valeur": 0.2, "unite": "part", "ou": "facade/toits/toitLidar.ts", "pourquoi": "L'axe des mesures se lit sur cette tranche haute des cellules.", "cas": [] },
    "PART_ECARTEE": { "valeur": 0.04, "unite": "part", "ou": "facade/toits/toitLidar.ts", "pourquoi": "Sans cette part des plus hautes, cheminee ou arbre, pour lire l'axe des mesures.", "cas": [] },
    "ALLONGEMENT_MIN": { "valeur": 2.5, "unite": "rapport", "ou": "facade/toits/toitLidar.ts", "pourquoi": "L'allongement qu'il faut a la tranche haute pour dire une direction de faitage.", "cas": [] },
