    "facades.ia.voteMemeU": {"valeur": 0.05, "unite": "part", "ou": "facade/regles/facades/ia.ts", "pourquoi": "Vote des trois passes (le mode de production depuis le 29 octobre 2026) : deux pointes, deux elements du toit de deux passes sont le meme a cette part de la largeur du mur pres.", "cas": []},
    "facades.ia.voteMemeBaie": {"valeur": 0.3, "unite": "part", "ou": "facade/regles/facades/ia.ts", "pourquoi": "Vote de trois passes : deux boites de deux passes sont la meme baie a partir de ce recouvrement (intersection sur union), le seuil du vote de l'ancien renfort (MEME_BOITE).", "cas": []},
    "facades.ia.voteMemeEtendue": {"valeur": 0.5, "unite": "part", "ou": "facade/regles/facades/ia.ts", "pourquoi": "Vote de trois passes : deux etendues (appentis, corps, cache) ou deux zones d'un parement de deux passes sont la meme a partir de ce recouvrement.", "cas": []},
